package storage
import("context";"errors";"fmt";"strconv";"strings";"time";"github.com/gotd/td/telegram/message";"github.com/gotd/td/telegram/uploader";"github.com/gotd/td/tg")
type Client struct{target string}
func New(target string)(*Client,error){target=strings.TrimSpace(target);if target==""{return nil,errors.New("STORAGE_TARGET is required")};return &Client{target:target},nil}
func(c *Client)Resolve(ctx context.Context,api *tg.Client)(tg.InputPeerClass,error){
if api==nil{return nil,errors.New("personal Telegram session is not connected")}
if !strings.HasPrefix(c.target,"-"){username:=strings.TrimPrefix(c.target,"@");r,e:=api.ContactsResolveUsername(ctx,&tg.ContactsResolveUsernameRequest{Username:username});if e!=nil{return nil,fmt.Errorf("resolve storage username: %w",e)};switch p:=r.Peer.(type){case *tg.PeerChannel:for _,v:=range r.Chats{if ch,ok:=v.(*tg.Channel);ok&&ch.ID==p.ChannelID{return &tg.InputPeerChannel{ChannelID:ch.ID,AccessHash:ch.AccessHash},nil}};case *tg.PeerChat:return &tg.InputPeerChat{ChatID:p.ChatID},nil};return nil,errors.New("Telegram did not return storage peer access data")}
id,e:=strconv.ParseInt(c.target,10,64);if e!=nil||id>=0{return nil,fmt.Errorf("invalid STORAGE_TARGET %q",c.target)}
q,cancel:=context.WithTimeout(ctx,15*time.Second);defer cancel();r,e:=api.MessagesGetDialogs(q,&tg.MessagesGetDialogsRequest{OffsetPeer:&tg.InputPeerEmpty{},Limit:200,Hash:0});if e!=nil{return nil,fmt.Errorf("read your account dialogs: %w",e)}
var chats []tg.ChatClass;switch v:=r.(type){case *tg.MessagesDialogs:chats=v.Chats;case *tg.MessagesDialogsSlice:chats=v.Chats;default:return nil,fmt.Errorf("unsupported dialogs response %T",r)}
if id<=-1000000000000{cid:=-id-1000000000000;for _,v:=range chats{if ch,ok:=v.(*tg.Channel);ok&&int64(ch.ID)==cid{if ch.AccessHash==0{return nil,errors.New("storage channel access hash unavailable")};return &tg.InputPeerChannel{ChannelID:ch.ID,AccessHash:ch.AccessHash},nil}}}else{cid:=-id;for _,v:=range chats{if ch,ok:=v.(*tg.Chat);ok&&int64(ch.ID)==cid{return &tg.InputPeerChat{ChatID:ch.ID},nil}}}
return nil,fmt.Errorf("storage destination %s is not in your personal account dialogs; that account must be a member",c.target)}
func(c *Client)UploadPath(ctx context.Context,api *tg.Client,peer tg.InputPeerClass,path,filename,mime,caption string)(tg.UpdatesClass,error){if api==nil||peer==nil{return nil,errors.New("personal account and storage peer are required")};u:=uploader.NewUploader(api).WithThreads(4);s:=message.NewSender(api).WithUploader(u);f,e:=u.FromPath(ctx,path);if e!=nil{return nil,fmt.Errorf("upload file: %w",e)};doc:=message.UploadedDocument(f).Filename(filename).MIME(mime);_=caption;return s.To(peer).Media(ctx,doc)}
